//! Replays a trace generated by the shipped TypeScript class, so the Rust port
//! is checked against the implementation it replaces rather than only against
//! the ported oracle.
//!
//! Set `LMCS_TERMINAL_HISTORY_TRACE` to a trace file; the test skips when unset.
//! Regenerate one with:
//! `node apps/server/scripts/terminal-history-trace.ts > /tmp/trace.txt`

use lmcs_terminal_history::{BoundedHistory, UNLIMITED_BYTES};

fn unhex(value: &str) -> Vec<u8> {
    (0..value.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&value[index..index + 2], 16).expect("hex byte"))
        .collect()
}

fn current(history: &mut Option<BoundedHistory>) -> &mut BoundedHistory {
    history.as_mut().expect("a config precedes every record")
}

#[test]
fn replays_the_typescript_trace_from_the_shipped_class() {
    let Some(path) = std::env::var_os("LMCS_TERMINAL_HISTORY_TRACE") else {
        eprintln!("skipped: LMCS_TERMINAL_HISTORY_TRACE is unset, so no cross-language check ran");
        return;
    };
    let text = std::fs::read_to_string(&path).expect("the trace file is readable");

    let mut limits: Option<(usize, usize)> = None;
    let mut history: Option<BoundedHistory> = None;
    let mut configs = 0;
    let mut comparisons = 0;

    for (line_number, line) in text.lines().enumerate() {
        let (op, rest) = line.split_once(' ').unwrap_or((line, ""));
        match op {
            "C" => {
                let mut fields = rest.split(' ');
                let max_lines = fields.next().unwrap().parse().expect("maxLines");
                let max_bytes = match fields.next().unwrap() {
                    "INF" => UNLIMITED_BYTES,
                    field => field.parse().expect("maxBytes"),
                };
                limits = Some((max_lines, max_bytes));
                configs += 1;
            }
            "I" => {
                let (max_lines, max_bytes) = limits.expect("C precedes I");
                history = Some(BoundedHistory::with_limits(
                    max_lines,
                    max_bytes,
                    &unhex(rest),
                ));
            }
            "S" => current(&mut history).append(&unhex(rest)),
            "L" => current(&mut history).clear(),
            "E" => {
                let expected = unhex(rest);
                let actual = current(&mut history).value();
                assert_eq!(
                    actual,
                    expected,
                    "line {}: Rust kept {:?}, the shipped class kept {:?}",
                    line_number + 1,
                    String::from_utf8_lossy(&actual),
                    String::from_utf8_lossy(&expected)
                );
                comparisons += 1;
            }
            "" => {}
            other => panic!("unknown record {other:?} on line {}", line_number + 1),
        }
    }

    assert_eq!(
        configs, 25,
        "five byte budgets crossed with five line budgets"
    );
    assert!(
        comparisons >= 7_000,
        "the trace only made {comparisons} comparisons"
    );
}
